// ------------------------------------------------------------------ agente Geoprog (entrar con el codigo del enfermero)
function geoFecHoy(){var f=fecDe(Date.now());return f.slice(0,4)+'-'+f.slice(4,6)+'-'+f.slice(6,8);}
async function cargarEnfermeros(){var sel=$('#gSel');if(!sel)return;try{var d=await api('geoprog',{geo:'lista'});sel.innerHTML='<option value="">— elige de la lista —</option>'+(d.enfermeros||[]).map(function(e){return '<option value="'+esc(e.id)+'">'+esc(e.nombre)+'</option>';}).join('');}catch(e){}}
function geoInit(){var f=$('#gFec');if(f&&!f.value)f.value=geoFecHoy();cargarEnfermeros();}
if($('#gSel'))$('#gSel').addEventListener('change',function(){if($('#gSel').value)$('#gCod').value='';});
if($('#gTraer'))$('#gTraer').addEventListener('click',async function(){
  msg('#gMsg','');var b=$('#gTraer');
  var fec=($('#gFec').value||'').replace(/-/g,'');
  var id=$('#gSel').value,codigo=$('#gCod').value.trim();
  if(fec.length!==8){msg('#gMsg','Elige la fecha de la ruta.');return;}
  if(!id&&!codigo){msg('#gMsg','Escribe el código del licenciad@.');return;}
  b.disabled=true;b.textContent='Entrando a Geoprog…';
  try{
    var d=await api('geoprog',{geo:'traer',id:id,codigo:codigo,fec:fec});
    if(!d.rows||!d.rows.length){msg('#gMsg','Geoprog no devolvió pacientes para ese día.','aviso');}
    else{
      $('#tLista').value='RUTA PADOMI '+JSON.stringify({fec:d.fec,prof:d.prof,rows:d.rows});
      $('#tLista').dispatchEvent(new Event('input'));
      msg('#gMsg',(d.prof?d.prof+' · ':'')+d.rows.length+' pacientes. Armando ruta…','ok');
      $('#bArmar').click();
    }
  }catch(e){msg('#gMsg',e.message);}
  b.disabled=false;b.textContent='📥 Traer pacientes de Geoprog';
});
